SET NAMES utf8mb4;

ON DUPLICATE KEY UPDATE category_id=VALUES(category_id),name=VALUES(name),brand=VALUES(brand),price=VALUES(price),price_display=VALUES(price_display),subscription=VALUES(subscription),score=VALUES(score),verdict=VALUES(verdict),best_for=VALUES(best_for),image_url=VALUES(image_url),image_key=VALUES(image_key),alt_text=VALUES(alt_text),merchant_name=VALUES(merchant_name),merchant_url=VALUES(merchant_url),updated_label=VALUES(updated_label),rank_order=VALUES(rank_order),is_featured=VALUES(is_featured),is_published=TRUE;

ON DUPLICATE KEY UPDATE category_id=VALUES(category_id),product_a_id=VALUES(product_a_id),product_b_id=VALUES(product_b_id),product_a_name=VALUES(product_a_name),product_b_name=VALUES(product_b_name),verdict=VALUES(verdict),content_json=VALUES(content_json),updated_label=VALUES(updated_label),sort_order=VALUES(sort_order),is_published=TRUE;

SELECT x.id,v.pick_name,v.audience,v.sort_order FROM comparisons x JOIN (
SELECT 'neakasa-m1-plus-vs-litter-robot-4' slug,'Neakasa M1 Plus' pick_name,'Cats that prefer an open-top entry and owners checking the larger footprint.' audience,1 sort_order UNION ALL SELECT 'neakasa-m1-plus-vs-litter-robot-4','Whisker Litter-Robot 4','Multi-cat owners prioritizing a mature rotating workflow and established app.' ,2 UNION ALL
SELECT 'petlibro-air-vs-honeyguardian-a36','PETLIBRO Air Automatic Feeder','Small spaces and owners who want a compact basic feeder.',1 UNION ALL SELECT 'petlibro-air-vs-honeyguardian-a36','HoneyGuaridan A36 Automatic Feeder','Two pets sharing a dual-bowl schedule.',2 UNION ALL
SELECT 'petcube-360-vs-blink-mini-2','Petcube Cam 360','Owners who value pan-and-tilt coverage.',1 UNION ALL SELECT 'petcube-360-vs-blink-mini-2','Blink Mini 2','Owners who need basic live video at the lowest hardware price.',2 UNION ALL
SELECT 'petsafe-drinkwell-vs-dockstream-2','PetSafe Drinkwell Ceramic Pagoda','Pets that respond to a visible stream.',1 UNION ALL SELECT 'petsafe-drinkwell-vs-dockstream-2','PETLIBRO Dockstream 2 Smart Water Fountain','Owners who want app-visible hydration trends.',2 UNION ALL
SELECT 'sureflap-vs-hightech-pet-door','SureFlap Microchip Pet Door Connect','Cats and smaller pets needing selective microchip access.',1 UNION ALL SELECT 'sureflap-vs-hightech-pet-door','High Tech Pet Power Pet Door PX-2','Larger dogs and dedicated installations.',2 UNION ALL
SELECT 'petpace-vs-fitbark','PetPace Smart Collar','Vet-guided broader wellness monitoring.',1 UNION ALL SELECT 'petpace-vs-fitbark','FitBark 2','Simple activity trends without a subscription.',2
) v ON v.slug=x.slug WHERE NOT EXISTS (SELECT 1 FROM comparison_best_for b WHERE b.comparison_id=x.id AND b.pick_name=v.pick_name);

ON DUPLICATE KEY UPDATE title=VALUES(title),pick_product_id=VALUES(pick_product_id),pick_name=VALUES(pick_name),budget=VALUES(budget),tradeoff=VALUES(tradeoff),content_json=VALUES(content_json),sort_order=VALUES(sort_order),is_published=TRUE;

ON DUPLICATE KEY UPDATE category_id=VALUES(category_id),product_id=VALUES(product_id),product_name=VALUES(product_name),problem=VALUES(problem),title=VALUES(title),description=VALUES(description),difficulty=VALUES(difficulty),estimated_time=VALUES(estimated_time),updated_label=VALUES(updated_label),content_json=VALUES(content_json),sort_order=VALUES(sort_order),is_published=TRUE;

SELECT g.id,v.instruction,v.sort_order FROM troubleshooting_guides g JOIN (
SELECT 'neakasa-m1-plus-open-top-not-cycling' slug,'Reseat the waste drawer and confirm the unit is level.' instruction,1 sort_order UNION ALL SELECT 'neakasa-m1-plus-open-top-not-cycling','Check the power connection and weight-detection area.',2 UNION ALL SELECT 'neakasa-m1-plus-open-top-not-cycling','Remove loose litter from the cycle path.',3 UNION ALL SELECT 'neakasa-m1-plus-open-top-not-cycling','Run one supervised empty cycle.',4 UNION ALL
SELECT 'petlibro-air-not-dispensing','Confirm the meal schedule and portion are saved.',1 UNION ALL SELECT 'petlibro-air-not-dispensing','Check for a bridge or blockage in the food path.',2 UNION ALL SELECT 'petlibro-air-not-dispensing','Confirm power and backup battery status.',3 UNION ALL SELECT 'petlibro-air-not-dispensing','Run one supervised manual portion.',4 UNION ALL
SELECT 'tractive-cat-mini-location-stale','Confirm the tracker is charged and attached securely.',1 UNION ALL SELECT 'tractive-cat-mini-location-stale','Move outdoors or to an area with known coverage.',2 UNION ALL SELECT 'tractive-cat-mini-location-stale','Start live mode and wait for a fresh location.',3 UNION ALL SELECT 'tractive-cat-mini-location-stale','Contact support if the timestamp remains stale.',4 UNION ALL
SELECT 'blink-mini-2-camera-offline','Confirm the camera light and power adapter are working.',1 UNION ALL SELECT 'blink-mini-2-camera-offline','Check the configured Wi-Fi band and router distance.',2 UNION ALL SELECT 'blink-mini-2-camera-offline','Restart the camera and app once.',3 UNION ALL SELECT 'blink-mini-2-camera-offline','Re-pair only after noting the existing settings.',4 UNION ALL
SELECT 'petsafe-drinkwell-low-flow','Disconnect power and remove the pump cover.',1 UNION ALL SELECT 'petsafe-drinkwell-low-flow','Clear hair and debris from the intake and impeller.',2 UNION ALL SELECT 'petsafe-drinkwell-low-flow','Clean the spout and water path.',3 UNION ALL SELECT 'petsafe-drinkwell-low-flow','Refill to the marked level and run one supervised test.',4 UNION ALL
SELECT 'hightech-px2-door-not-opening','Replace or recharge the collar-key battery.',1 UNION ALL SELECT 'hightech-px2-door-not-opening','Confirm the door has power and the flap is aligned.',2 UNION ALL SELECT 'hightech-px2-door-not-opening','Test the manual override without forcing the motor.',3 UNION ALL SELECT 'hightech-px2-door-not-opening','Contact support if the motor strains or remains locked.',4 UNION ALL
SELECT 'fitbark-2-not-syncing','Charge the tracker and keep it near the phone.',1 UNION ALL SELECT 'fitbark-2-not-syncing','Open the app and wait for the sync indicator.',2 UNION ALL SELECT 'fitbark-2-not-syncing','Toggle Bluetooth once if the device is not found.',3 UNION ALL SELECT 'fitbark-2-not-syncing','Contact support if a charged device still will not sync.',4
) v ON v.slug=g.slug WHERE NOT EXISTS (SELECT 1 FROM troubleshooting_steps s WHERE s.guide_id=g.id AND s.instruction=v.instruction);
