INSERT INTO products
  (external_id,category_id,slug,name,brand,price,price_display,subscription,score,verdict,best_for,image_url,image_key,alt_text,merchant_name,merchant_url,updated_label,rank_order,is_featured,is_published)
VALUES
('litter-neakasa',(SELECT id FROM categories WHERE slug='automatic-litter-boxes'),'neakasa-m1-plus','Neakasa M1 Plus','Neakasa',549.00,'$549','Optional app features',4.0,'An open-top design with a generous entry and useful waste handling, balanced against a larger footprint.','Cats that dislike enclosed globes','https://images.unsplash.com/photo-1513245543132-31f507417b26?w=700&h=520&fit=crop&auto=format','products/neakasa-m1-plus.webp','Neakasa M1 Plus automatic litter box','Neakasa','https://neakasa.com/','Sep 2026',7,FALSE,TRUE),
('litter-leos',(SELECT id FROM categories WHERE slug='automatic-litter-boxes'),'litterbox-leos-loo-too','Leo''s Loo Too','Smarty Pear',699.00,'$699','Optional app features',3.9,'A premium globe unit with odor control and app monitoring, but replacement parts and service coverage need checking.','Owners wanting premium odor control','https://images.unsplash.com/photo-1592194996308-7b43878e84a6?w=700&h=520&fit=crop&auto=format','products/leos-loo-too.webp','Leo''s Loo Too automatic litter box','Smarty Pear','https://smartypear.com/','Sep 2026',8,FALSE,TRUE),
('feeder-air',(SELECT id FROM categories WHERE slug='smart-pet-feeders'),'petlibro-air-feeder','PETLIBRO Air Automatic Feeder','PETLIBRO',59.99,'$59.99','None required',3.8,'A compact feeder for straightforward portions and schedules, without a camera or recurring plan.','Small spaces and basic schedules','https://images.unsplash.com/photo-1516734212186-a967f81ad0d7?w=700&h=520&fit=crop&auto=format','products/petlibro-air-feeder.webp','PETLIBRO Air automatic pet feeder','PETLIBRO','https://petlibro.com/','Sep 2026',6,FALSE,TRUE),
('feeder-honey',(SELECT id FROM categories WHERE slug='smart-pet-feeders'),'honeyguardian-a36','HoneyGuaridan A36 Automatic Feeder','HoneyGuaridan',69.99,'$69.99','None required',3.6,'A budget schedule feeder with dual-bowl dispensing and more portion variance at very small meals.','Two-pet households sharing a schedule','https://images.unsplash.com/photo-1558788353-f76d92427f16?w=700&h=520&fit=crop&auto=format','products/honeyguardian-a36.webp','HoneyGuaridan A36 automatic feeder','HoneyGuaridan','https://honeyguardian.com/','Sep 2026',7,FALSE,TRUE),
('tracker-catmini',(SELECT id FROM categories WHERE slug='gps-pet-trackers'),'tractive-gps-cat-mini','Tractive GPS CAT Mini','Tractive',49.99,'$49.99','$9.99/mo',3.8,'A lightweight cat tracker with live location and activity trends, limited by cellular coverage and subscription cost.','Outdoor cats that tolerate a tracker','https://images.unsplash.com/photo-1514888286974-6c03e2ca1dba?w=700&h=520&fit=crop&auto=format','products/tractive-gps-cat-mini.webp','Tractive GPS CAT Mini tracker','Tractive','https://tractive.com/','Sep 2026',6,FALSE,TRUE),
('tracker-garmin',(SELECT id FROM categories WHERE slug='gps-pet-trackers'),'garmin-alpha-t20','Garmin Alpha T 20','Garmin',249.99,'$249.99','No cellular plan; compatible handheld required',3.7,'A long-range training and tracking collar for rural use, with higher upfront cost and a more complex setup.','Working dogs and rural tracking','https://images.unsplash.com/photo-1552053831-71594a27632d?w=700&h=520&fit=crop&auto=format','products/garmin-alpha-t20.webp','Garmin Alpha T 20 dog tracking collar','Garmin','https://www.garmin.com/','Sep 2026',7,FALSE,TRUE),
('camera-petcube',(SELECT id FROM categories WHERE slug='pet-cameras'),'petcube-cam-360','Petcube Cam 360','Petcube',49.99,'$49.99','Optional plan',3.7,'A compact pan-and-tilt camera with two-way audio and a lower entry price than treat-dispensing models.','Room coverage on a smaller budget','https://images.unsplash.com/photo-1558008258-3256797b43f3?w=700&h=440&fit=crop&auto=format','products/petcube-cam-360.webp','Petcube Cam 360 pet camera','Petcube','https://petcube.com/','Sep 2026',5,FALSE,TRUE),
('camera-blink',(SELECT id FROM categories WHERE slug='pet-cameras'),'blink-mini-2','Blink Mini 2','Blink',39.99,'$39.99','Optional Blink subscription',3.5,'A low-cost indoor camera with basic detection and optional cloud recording, but limited pet-specific interaction.','Basic live video on a tight budget','https://images.unsplash.com/photo-1537151608828-ea2b11777ee8?w=700&h=440&fit=crop&auto=format','products/blink-mini-2.webp','Blink Mini 2 indoor camera for pets','Blink','https://blinkforhome.com/','Sep 2026',6,FALSE,TRUE),
('water-drinkwell',(SELECT id FROM categories WHERE slug='smart-water-fountains'),'petsafe-drinkwell-cep','PetSafe Drinkwell Ceramic Pagoda','PetSafe',89.99,'$89.99','Replacement filters',3.6,'A ceramic fountain with a visible stream and no required app, traded against filter replacement and more parts to clean.','Pets that prefer a visible stream','https://images.unsplash.com/photo-1589924691106-073b0f4d7f0a?w=700&h=520&fit=crop&auto=format','products/petsafe-drinkwell-ceramic.webp','PetSafe Drinkwell Ceramic Pagoda fountain','PetSafe','https://www.petsafe.com/','Sep 2026',5,FALSE,TRUE),
('door-hightech',(SELECT id FROM categories WHERE slug='smart-pet-doors'),'high-tech-pet-px2','High Tech Pet Power Pet Door PX-2','High Tech Pet',399.00,'$399','None required',3.7,'A motorized door designed for larger pets with collar-based access and a substantial installation commitment.','Large dogs and dedicated installations','https://images.unsplash.com/photo-1544568100-847a948585b9?w=700&h=520&fit=crop&auto=format','products/high-tech-pet-px2.webp','High Tech Pet Power Pet Door PX-2','High Tech Pet','https://www.hitecpet.com/','Sep 2026',4,FALSE,TRUE),
('health-fitbark',(SELECT id FROM categories WHERE slug='pet-health-monitors'),'fitbark-2','FitBark 2','FitBark',69.95,'$69.95','None required',3.6,'An activity-focused wearable that is simpler and lighter than broader wellness-monitoring collars.','Owners tracking activity trends without a plan','https://images.unsplash.com/photo-1558788353-f76d92427f16?w=700&h=520&fit=crop&auto=format','products/fitbark-2.webp','FitBark 2 dog activity monitor','FitBark','https://www.fitbark.com/','Sep 2026',4,FALSE,TRUE)
INSERT INTO comparisons
  (slug,category_id,product_a_id,product_b_id,product_a_name,product_b_name,verdict,views_count,read_time,updated_label,content_json,sort_order,is_featured,is_published)
VALUES
('neakasa-m1-plus-vs-litter-robot-4',(SELECT id FROM categories WHERE slug='automatic-litter-boxes'),(SELECT id FROM products WHERE slug='neakasa-m1-plus'),(SELECT id FROM products WHERE slug='litter-robot-4'),'Neakasa M1 Plus','Whisker Litter-Robot 4','An open-top entry and a rotating globe take different approaches to cat acceptance, waste handling, app detail, and maintenance.',0,'9 min read','Sep 2026',JSON_OBJECT('matchType','direct-alternatives','matchLabel','Direct alternatives','whyCompare','Both target premium buyers who want less daily scooping but differ in structure and cat fit.','decisionQuestion','Will an open-top design or a mature rotating workflow suit your cats better?'),19,FALSE,TRUE),
('petlibro-air-vs-honeyguardian-a36',(SELECT id FROM categories WHERE slug='smart-pet-feeders'),(SELECT id FROM products WHERE slug='petlibro-air-feeder'),(SELECT id FROM products WHERE slug='honeyguardian-a36'),'PETLIBRO Air Automatic Feeder','HoneyGuaridan A36 Automatic Feeder','Both cover scheduled feeding without a subscription; portion repeatability, bowl layout, and household pet access separate them.',0,'7 min read','Sep 2026',JSON_OBJECT('matchType','value-alternatives','matchLabel','Value alternatives','whyCompare','These are simple feeders for owners who do not need a camera or cloud workflow.','decisionQuestion','Which low-cost schedule and bowl setup better fits your pets?'),20,FALSE,TRUE),
('petcube-360-vs-blink-mini-2',(SELECT id FROM categories WHERE slug='pet-cameras'),(SELECT id FROM products WHERE slug='petcube-cam-360'),(SELECT id FROM products WHERE slug='blink-mini-2'),'Petcube Cam 360','Blink Mini 2','Petcube adds pan-and-tilt and pet-oriented controls, while Blink keeps the hardware price low with a general indoor-camera workflow.',0,'7 min read','Sep 2026',JSON_OBJECT('matchType','specialist-vs-generalist','matchLabel','Specialist vs generalist','whyCompare','Both provide affordable live video but make different trade-offs around coverage and pet features.','decisionQuestion','Do you need pet-focused coverage or the lowest-cost basic camera?'),21,FALSE,TRUE),
('petsafe-drinkwell-vs-dockstream-2',(SELECT id FROM categories WHERE slug='smart-water-fountains'),(SELECT id FROM products WHERE slug='petsafe-drinkwell-cep'),(SELECT id FROM products WHERE slug='petlibro-dockstream-2'),'PetSafe Drinkwell Ceramic Pagoda','PETLIBRO Dockstream 2 Smart Water Fountain','A visible-stream ceramic fountain is compared with an app-connected fountain focused on hydration trends and a more contained water path.',0,'8 min read','Sep 2026',JSON_OBJECT('matchType','feature-tradeoff','matchLabel','Different approaches','whyCompare','Both aim to encourage drinking but prioritize different cleaning, monitoring, and stream designs.','decisionQuestion','Should you prioritize a visible stream or app-visible hydration trends?'),22,FALSE,TRUE),
('sureflap-vs-hightech-pet-door',(SELECT id FROM categories WHERE slug='smart-pet-doors'),(SELECT id FROM products WHERE slug='sureflap-microchip-pet-door-connect'),(SELECT id FROM products WHERE slug='high-tech-pet-px2'),'SureFlap Microchip Pet Door Connect','High Tech Pet Power Pet Door PX-2','Microchip-led selective access for smaller pets meets a motorized collar-key door intended for larger installations.',0,'8 min read','Sep 2026',JSON_OBJECT('matchType','fit-first','matchLabel','Fit-first decision','whyCompare','Pet size and installation constraints dominate this choice before connected features.','decisionQuestion','Which access technology fits your pet and opening?'),23,FALSE,TRUE),
('petpace-vs-fitbark',(SELECT id FROM categories WHERE slug='pet-health-monitors'),(SELECT id FROM products WHERE slug='petpace-smart-collar'),(SELECT id FROM products WHERE slug='fitbark-2'),'PetPace Smart Collar','FitBark 2','PetPace emphasizes broader wellness signals with a plan; FitBark keeps activity tracking simpler and subscription-free.',0,'7 min read','Sep 2026',JSON_OBJECT('matchType','scope-tradeoff','matchLabel','Scope trade-off','whyCompare','The right choice depends on whether broader signals justify more setup and ongoing cost.','decisionQuestion','Do you need broader wellness context or simple activity trends?'),24,FALSE,TRUE)
