('best-visible-stream-water-fountain',(SELECT id FROM categories WHERE slug='smart-water-fountains'),'Water Fountains','Best fountain for a visible stream',(SELECT id FROM products WHERE slug='petsafe-drinkwell-cep'),'PetSafe Drinkwell Ceramic Pagoda','$89.99 plus filters','Ceramic parts and filters add cleaning and replacement work.',(SELECT image_url FROM categories WHERE slug='smart-water-fountains'),'best-picks/visible-stream-fountain.webp',JSON_OBJECT('why','Visible water movement can appeal to some pets','notFor','Owners who want app monitoring or minimal parts'),17,TRUE),
