INSERT INTO troubleshooting_guides
  (slug,category_id,product_id,product_name,problem,title,description,difficulty,estimated_time,views_count,updated_label,content_json,sort_order,is_published)
VALUES
('neakasa-m1-plus-open-top-not-cycling',(SELECT id FROM categories WHERE slug='automatic-litter-boxes'),(SELECT id FROM products WHERE slug='neakasa-m1-plus'),'Neakasa M1 Plus','Open-top unit does not start a cleaning cycle','Neakasa M1 Plus not cycling','Check drawer seating, weight detection, power, and the documented reset sequence.','Moderate','20 min',0,'Sep 2026',JSON_OBJECT('safety','Keep pets away from the unit during a supervised cycle.'),18,TRUE),
('petlibro-air-not-dispensing',(SELECT id FROM categories WHERE slug='smart-pet-feeders'),(SELECT id FROM products WHERE slug='petlibro-air-feeder'),'PETLIBRO Air Automatic Feeder','Feeder skips a scheduled portion','PETLIBRO Air not dispensing','Verify the schedule, food path, portion setting, and battery or mains power.','Easy fix','15 min',0,'Sep 2026',JSON_OBJECT('safety','Provide a reliable backup meal while testing a missed schedule.'),19,TRUE),
('tractive-cat-mini-location-stale',(SELECT id FROM categories WHERE slug='gps-pet-trackers'),(SELECT id FROM products WHERE slug='tractive-gps-cat-mini'),'Tractive GPS CAT Mini','Cat location has not updated','Tractive CAT Mini location stale','Check battery, coverage, live mode, and whether the tracker is attached as expected.','Moderate','15 min',0,'Sep 2026',JSON_OBJECT('safety','Begin a physical search immediately if an outdoor cat is missing.'),20,TRUE),
('blink-mini-2-camera-offline',(SELECT id FROM categories WHERE slug='pet-cameras'),(SELECT id FROM products WHERE slug='blink-mini-2'),'Blink Mini 2','Camera is offline','Blink Mini 2 offline','Check power, Wi-Fi band, router distance, and account pairing before resetting the camera.','Easy fix','15 min',0,'Sep 2026',JSON_OBJECT('safety','Do not rely on a camera as the only safety check for a pet.'),21,TRUE),
('petsafe-drinkwell-low-flow',(SELECT id FROM categories WHERE slug='smart-water-fountains'),(SELECT id FROM products WHERE slug='petsafe-drinkwell-cep'),'PetSafe Drinkwell Ceramic Pagoda','Water flow is weak','Drinkwell fountain weak flow','Clean the pump, intake screen, spout, and water path, then confirm the tank level.','Easy fix','15 min',0,'Sep 2026',JSON_OBJECT('safety','Disconnect power before opening or cleaning the pump.'),22,TRUE),
('hightech-px2-door-not-opening',(SELECT id FROM categories WHERE slug='smart-pet-doors'),(SELECT id FROM products WHERE slug='high-tech-pet-px2'),'High Tech Pet Power Pet Door PX-2','Motorized door does not open for the pet','High Tech Pet door not opening','Check collar-key battery, door power, alignment, and manual override behavior.','Moderate','20 min',0,'Sep 2026',JSON_OBJECT('safety','Keep the manual access mode available while testing.'),23,TRUE),
('fitbark-2-not-syncing',(SELECT id FROM categories WHERE slug='pet-health-monitors'),(SELECT id FROM products WHERE slug='fitbark-2'),'FitBark 2','Activity data is not syncing','FitBark 2 not syncing','Charge the device, confirm Bluetooth range, and allow a full sync before interpreting missing activity.','Easy fix','15 min',0,'Sep 2026',JSON_OBJECT('safety','A missing reading is not evidence that a pet is inactive or well.'),24,TRUE)
